for i, slide in enumerate(slides):
    step_items = ''.join('<li><i>%d</i><span>%s</span></li>' % (n + 1, s) for n, s in enumerate(slide['steps']))
    slide_html.append(
        '<article class="ts-slide" data-ts-slide="%d">'
        '<div class="ts-stage">%s</div>'
        '<div class="ts-guide"><span class="ts-tag">%s</span><h3>%s</h3><ol>%s</ol></div>'
        '</article>' % (i, slide['visual'], slide['tag'], slide['title'], step_items)
    )
    dots.append('<button type="button" class="ts-dot%s" data-ts-go="%d" aria-label="مرحله %d"></button>' % (' on' if i == 0 else '', i, i + 1))

